// KB offline cache (website and Android app). Generated by build/make-site.js: VERSION and FILES are filled in.
// Same-site files: served from the cache straight away and refreshed in the background, so the app opens
// instantly and works on a plane. Calls to Google, AI providers and the licence server are never touched.
const VERSION = "__VERSION__";
const FILES = __FILES__;
const CACHE = "kb-" + VERSION;

self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith("kb-") && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener("fetch", (e) => {
  const req = e.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== location.origin || !url.pathname.startsWith(new URL("./", location.href).pathname)) return;
  if (req.mode === "navigate") {
    // Pages: network first (new versions show up), the cached app when offline.
    e.respondWith(fetch(req).catch(() => caches.match("index.html", { ignoreSearch: true }).then((r) => r || caches.match("./"))));
    return;
  }
  e.respondWith(caches.open(CACHE).then(async (c) => {
    const hit = await c.match(req, { ignoreSearch: true });
    const fresh = fetch(req).then((r) => { if (r.ok) c.put(req, r.clone()); return r; }).catch(() => hit);
    return hit || fresh;
  }));
});
